#!/usr/bin/env node
// Bundles the motion vocabulary (dist/vocab/*.js, tsc output) into single classic scripts, no bundler dependency:
//   dist/motion-vocab.js        the film shelf file: global MV (components + bind), what /vendor/motion-vocab.js serves
//   dist/motion-vocab-demo.js   MV + MV.demo + MV.catalogue, for compreel pages and the render tests
//   dist/motion-catalogue.json  xjp.motion-catalogue.v1 (the desk's and compreel's catalogue)
// Each module becomes a function scope; `import {a} from "./x.js"` becomes a read of the module table, so names never collide.
// Run after `tsc` (npm run build:vocab does both). Deterministic: the same sources give the same bytes.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC = path.join(ROOT, "dist", "vocab");
const pkg = JSON.parse(fs.readFileSync(path.join(ROOT, "package.json"), "utf8"));

function transform(name, code) {
  const exports = [];
  let out = code
    .replace(/^\/\/# sourceMappingURL=.*$/gm, "")
    .replace(/^import\s+type\s+[^;]+;\s*$/gm, "")
    .replace(/^import\s*\{([^}]*)\}\s*from\s*"\.\.?\/([\w-]+)\.js";\s*$/gm, (_, names, mod) => `const { ${names.split(",").map((s) => s.trim()).filter(Boolean).map((s) => s.replace(/\s+as\s+/, ": ")).join(", ")} } = __m[${JSON.stringify(mod)}];`)
    .replace(/^export\s*\{([^}]*)\}\s*from\s*"\.\/([\w-]+)\.js";\s*$/gm, (_, names, mod) => {
      const parts = names.split(",").map((s) => s.trim()).filter(Boolean);
      return parts.map((s) => { const [a, b] = s.split(/\s+as\s+/); exports.push([b ?? a, `__m[${JSON.stringify(mod)}].${a}`]); return ""; }).join("");
    })
    .replace(/^export\s+(async\s+function|function|const|let|class)\s+([\w$]+)/gm, (_, kw, id) => { exports.push([id, id]); return `${kw} ${id}`; });
  if (/^\s*(import|export)\b/m.test(out)) throw new Error(`${name}: an import/export form the bundler does not know:\n${out.match(/^\s*(import|export)\b.*$/m)[0]}`);
  const ret = exports.map(([k, v]) => (k === v ? k : `${k}: ${v}`)).join(", ");
  return `__m[${JSON.stringify(name)}] = (function () {\n${out.trim()}\nreturn { ${ret} };\n})();`;
}

function bundle(mods, tail, banner, guard) {
  // a module is a vocab file ("core") or a kit module one level up ("../ease"); either is keyed by its base name
  const body = mods.map((m) => transform(path.basename(m), fs.readFileSync(path.join(SRC, `${m}.js`), "utf8"))).join("\n");
  return `${banner}\n(function () {\n"use strict";\n${guard ? `if (window.MV && window.MV.VOCAB_VERSION === ${JSON.stringify(pkg.version)}) return; // loaded by an earlier shot\n` : ""}const __m = {};\n${body}\n${tail}\n})();\n`;
}

const CORE = ["../ease", "../measure", "easing", "core", "space", "parts", "type-input", "title", "captions", "logo", "transition", "device", "data", "timeline", "energy", "diagram", "index"];
const banner = (what) => `/* @xjp/motion-kit ${pkg.version} motion vocabulary (xjp.motion-vocab.v1): ${what}. Generated by packages/motion-kit/scripts/bundle-vocab.mjs from src/vocab; do not edit. */`;
const shelf = bundle(CORE, `window.MV = Object.assign({}, __m["index"], { VOCAB_VERSION: ${JSON.stringify(pkg.version)} });`, banner("the film shelf file, global MV"), true);
const demoJs = bundle([...CORE, "catalogue", "demo"], `window.MV = Object.assign({}, __m["index"], { VOCAB_VERSION: ${JSON.stringify(pkg.version)}, demo: __m["demo"].demo, demoOpts: __m["demo"].demoOpts, demoScene: __m["demo"].demoScene, catalogue: __m["catalogue"].catalogueDoc(${JSON.stringify(pkg.version)}) });`, banner("demo build: MV + MV.demo + MV.catalogue (compreel pages, render tests)"), false);
fs.writeFileSync(path.join(ROOT, "dist", "motion-vocab.js"), shelf);
fs.writeFileSync(path.join(ROOT, "dist", "motion-vocab-demo.js"), demoJs);
const { catalogueDoc, catalogueProblems } = await import(path.join(SRC, "catalogue.js"));
const doc = catalogueDoc(pkg.version);
const problems = catalogueProblems(doc);
if (problems.length) { console.error(problems.join("\n")); process.exit(1); }
fs.writeFileSync(path.join(ROOT, "dist", "motion-catalogue.json"), JSON.stringify(doc, null, 2) + "\n");
console.log(`motion-vocab.js ${shelf.length} B, motion-vocab-demo.js ${demoJs.length} B, catalogue ${doc.entries.length} entries`);
